32	+  cards: PaymentMethod[];
33	+  orderId: UUID;
34	+  /** The order's PaymentIntent secret — the same one the new-card form confirms. */
35	+  clientSecret: string;
36	+  total: number;
37	+  onSuccess: () => void;
38	+  /** Asks the page to re-fetch the saved cards, after one turns out to be gone. */
39	+  onCardsStale: () => void;
40	+}
41	+
42	+/** Sentinel for "type a new card" — the same trick CheckoutPage uses for "type a new address". */
43	+const NEW_CARD = 'NEW';
44	+
45	+/**
46	+ * The card to start on: the primary if it can still be used, else the first card that can, else
47	+ * a new card. The PO's rule — primary preselected, expired cards never selected.
48	+ */
49	+function defaultSelection(cards: PaymentMethod[]): string {
50	+  const usable = cards.filter((c) => !isCardExpired(c));
51	+  return (usable.find((c) => c.primary) ?? usable[0])?.id ?? NEW_CARD;
52	+}
53	+
54	+/**
55	+ * Pay with a saved card — or fall back to typing a new one — on the checkout's payment step.
56	+ *
57	+ * Must render INSIDE the page's <Elements> provider: `useStripe` reads from it, and the new-card
58	+ * branch is the ordinary StripePaymentForm, which needs it too. Both branches confirm the SAME
59	+ * PaymentIntent, which is why a declined saved card can be followed by a new card on the same order.
60	+ *
61	+ * Paying with a saved card is two calls:
62	+ *   1. our API puts the card on the PaymentIntent. We send OUR card id; the browser never holds
63	+ *      the Stripe token, so it cannot leak one.
64	+ *   2. Stripe.js confirms the intent with the clientSecret alone, using the card the server set.
65	+ *      `confirmCardPayment` also runs 3D Secure in a modal if the bank asks for it.
66	+ * The order is still only marked PAID by the server, exactly as for a new card.
67	+ */
68	+export function SavedCardPayment({
69	+  cards,
70	+  orderId,
71	+  clientSecret,
72	+  total,
73	+  onSuccess,
74	+  onCardsStale,
75	+}: Props) {
76	+  const stripe = useStripe();
77	+
78	+  // useId: a radio group needs one shared `name`, unique on the page. A hard-coded string would
