80	+  const groupName = useId();
81	+
82	+  const [chosen, setChosen] = useState<string>(() => defaultSelection(cards));
83	+  const [submitting, setSubmitting] = useState(false);
84	+  const [error, setError] = useState<string | null>(null);
85	+
86	+  /*
87	+   * The selection actually in force, DERIVED rather than synced with an effect.
88	+   *
89	+   * After a reload the chosen card may have vanished (deleted in another tab). Copying props into
90	+   * state with useEffect would render one frame with a stale selection; deriving it during render
91	+   * cannot be stale at all.
92	+   */
93	+  const usableIds = new Set(cards.filter((c) => !isCardExpired(c)).map((c) => c.id));
94	+  const selected = chosen === NEW_CARD || usableIds.has(chosen) ? chosen : defaultSelection(cards);
95	+  const selectedCard = cards.find((c) => c.id === selected);
96	+
97	+  async function payWithSavedCard() {
98	+    // Null until Stripe.js has loaded; the button is disabled until then anyway.
99	+    if (!stripe || !selectedCard) return;
100	+
101	+    setSubmitting(true);
102	+    setError(null);
103	+
104	+    // ---- 1. our API: put the card on the PaymentIntent -----------------------------------------
105	+    try {
106	+      await orderApi.selectSavedCard(orderId, selectedCard.id);
107	+    } catch (err) {
108	+      if (err instanceof ApiError && err.status === 404) {
