116	+        );
117	+      }
118	+      setSubmitting(false);
119	+      return;
120	+    }
121	+
122	+    // ---- 2. Stripe: confirm with the card the server set ---------------------------------------
123	+    const result = await stripe.confirmCardPayment(clientSecret);
124	+
125	+    if (result.error) {
