128	+      setError(customerSafeMessage(result.error));
129	+      setSubmitting(false);
130	+      return;
131	+    }
132	+
133	+    // Same contract as StripePaymentForm: Stripe accepted it, the server decides it is PAID.
134	+    onSuccess();
135	+  }
136	+
137	+  return (
138	+    <div>
139	+      {/*
140	+        A fieldset + legend, not a div: the legend is what gives the radio group its accessible
141	+        name, so a screen reader announces "Pay with" on entering it. `fs-6` cancels the large
142	+        font size Bootstrap's reboot gives every legend, so it looks the same as a label.
143	+      */}
144	+      <Form.Group as="fieldset" className="mb-3">
145	+        <Form.Label as="legend" className="fw-semibold mb-2 fs-6">
146	+          Pay with
