171	+                      Expires {String(card.expMonth).padStart(2, '0')}/{card.expYear}
172	+                    </span>
173	+                  )}
174	+                </span>
175	+              }
176	+            />
177	+          );
178	+        })}
179	+
180	+        <Form.Check
181	+          type="radio"
182	+          name={groupName}
183	+          id={`${groupName}-new`}
184	+          checked={selected === NEW_CARD}
185	+          disabled={submitting}
186	+          onChange={() => {
187	+            setChosen(NEW_CARD);
188	+            setError(null);
189	+          }}
190	+          label="Use a new card"
191	+        />
192	+      </Form.Group>
193	+
194	+      {selected === NEW_CARD || !selectedCard ? (
195	+        // The ordinary card form, unchanged. It confirms the same PaymentIntent, and the card it
196	+        // collects replaces any saved card the server put there after a decline.
197	+        <StripePaymentForm total={total} onSuccess={onSuccess} />
198	+      ) : (
199	+        <>
200	+          {error && (
201	+            <Alert variant="danger" className="mb-0">
202	+              {error}
203	+            </Alert>
204	+          )}
205	+
206	+          <Button
207	+            type="button"
208	+            variant="primary"
209	+            size="lg"
210	+            className="w-100 mt-3"
211	+            disabled={!stripe || submitting}
212	+            onClick={payWithSavedCard}
213	+          >
214	+            {submitting ? (
215	+              <>
216	+                <Spinner as="span" animation="border" size="sm" className="me-2" />
