218	+              </>
219	+            ) : (
220	+              `Pay ${formatMoney(total)} with ${cardLabel(selectedCard)}`
221	+            )}
222	+          </Button>
223	+        </>
224	+      )}
225	+    </div>
226	+  );
227	+}
