262	+import type { PaymentMethod } from '../types';
263	+
264	+/**
265	+ * Whether a saved card had expired by `now`.
266	+ *
267	+ * The same rule as the server's `UserPaymentMethod.isExpiredAt`: a card is valid THROUGH its
268	+ * expiry month, so "12/2026" still works on 31 December 2026. A card with no expiry recorded
269	+ * counts as not expired — Stripe always reports one for a card, and it decides at charge time
270	+ * anyway.
271	+ *
272	+ * This only decides what the checkout greys out. The server repeats the check and is the one that
273	+ * refuses, so a browser clock that is a few hours off at a month boundary cannot let an expired
274	+ * card through.
275	+ */
276	+export function isCardExpired(
277	+  card: Pick<PaymentMethod, 'expMonth' | 'expYear'>,
278	+  now: Date = new Date(),
279	+): boolean {
280	+  if (card.expMonth == null || card.expYear == null) return false;
281	+
282	+  // getMonth() is 0-based; expMonth is 1-based, as Stripe reports it.
283	+  const currentYear = now.getFullYear();
284	+  const currentMonth = now.getMonth() + 1;
285	+  return card.expYear < currentYear || (card.expYear === currentYear && card.expMonth < currentMonth);
286	+}
287	+
288	+/**
289	+ * "Visa ••4242" — how a saved card is named on buttons and in lists.
290	+ *
291	+ * Stripe reports the brand in lower case ("visa", "mastercard"), so it is capitalised here. Either
292	+ * field can in principle be null, and the label must never read "null ••null".
293	+ */
294	+export function cardLabel(card: Pick<PaymentMethod, 'brand' | 'last4'>): string {
295	+  const brand = card.brand ? card.brand.charAt(0).toUpperCase() + card.brand.slice(1) : 'Card';
296	+  return card.last4 ? `${brand} ••${card.last4}` : brand;
297	+}
